"""Buffered B-tree with amortized O(1) insertion.

Insertions are buffered at the root node. When the buffer fills,
it is flushed into the tree in bulk, amortizing the O(log n) cost
across many inserts. Lookup remains O(log n).
"""

from __future__ import annotations


class _Node:
    __slots__ = ("keys", "children", "leaf")

    def __init__(self, leaf: bool = False) -> None:
        self.keys: list[int] = []
        self.children: list[_Node] = []
        self.leaf = leaf


class BTree:
    def __init__(self, degree: int = 64, buffer_size: int = 64) -> None:
        if degree < 2:
            raise ValueError("degree must be >= 2")
        if buffer_size < 1:
            raise ValueError("buffer_size must be >= 1")
        self.degree = degree
        self.buffer_size = buffer_size
        self._root = _Node(leaf=True)
        self._buffer: list[int] = []

    # ------------------------------------------------------------------ #
    #  Public API
    # ------------------------------------------------------------------ #

    def insert(self, key: int) -> None:
        """Insert a key. Amortized O(1)."""
        self._buffer.append(key)
        if len(self._buffer) >= self.buffer_size:
            self._flush_buffer()

    def search(self, key: int) -> bool:
        """Return True if key exists. O(log n)."""
        if any(k == key for k in self._buffer):
            return True
        return self._search_node(self._root, key)

    def keys(self) -> list[int]:
        """Return all keys in sorted order."""
        result: list[int] = []
        self._collect(self._root, result)
        result.extend(self._buffer)
        result.sort()
        return result

    # ------------------------------------------------------------------ #
    #  Internal
    # ------------------------------------------------------------------ #

    def _flush_buffer(self) -> None:
        for key in self._buffer:
            self._insert_into_tree(key)
        self._buffer.clear()

    def _insert_into_tree(self, key: int) -> None:
        root = self._root
        if len(root.keys) == 2 * self.degree - 1:
            new_root = _Node()
            new_root.children.append(root)
            self._split_child(new_root, 0)
            self._root = new_root
        self._insert_non_full(self._root, key)

    def _insert_non_full(self, node: _Node, key: int) -> None:
        i = len(node.keys) - 1
        if node.leaf:
            node.keys.append(0)
            while i >= 0 and key < node.keys[i]:
                node.keys[i + 1] = node.keys[i]
                i -= 1
            node.keys[i + 1] = key
        else:
            while i >= 0 and key < node.keys[i]:
                i -= 1
            i += 1
            if len(node.children[i].keys) == 2 * self.degree - 1:
                self._split_child(node, i)
                if key > node.keys[i]:
                    i += 1
            self._insert_non_full(node.children[i], key)

    def _split_child(self, parent: _Node, index: int) -> None:
        t = self.degree
        child = parent.children[index]
        new_node = _Node(leaf=child.leaf)

        parent.keys.insert(index, child.keys[t - 1])
        parent.children.insert(index + 1, new_node)

        new_node.keys = child.keys[t:]
        child.keys = child.keys[: t - 1]

        if not child.leaf:
            new_node.children = child.children[t:]
            child.children = child.children[:t]

    def _search_node(self, node: _Node, key: int) -> bool:
        i = 0
        while i < len(node.keys) and key > node.keys[i]:
            i += 1
        if i < len(node.keys) and key == node.keys[i]:
            return True
        if node.leaf:
            return False
        return self._search_node(node.children[i], key)

    def _collect(self, node: _Node, out: list[int]) -> None:
        for i, k in enumerate(node.keys):
            if not node.leaf:
                self._collect(node.children[i], out)
            out.append(k)
        if not node.leaf:
            self._collect(node.children[len(node.keys)], out)


# ------------------------------------------------------------------ #
#  Quick demo
# ------------------------------------------------------------------ #
if __name__ == "__main__":
    import random

    tree = BTree(degree=8, buffer_size=32)
    values = random.sample(range(100_000), 10_000)

    for v in values:
        tree.insert(v)

    assert all(tree.search(v) for v in values)
    assert not tree.search(-1)
    assert tree.keys() == sorted(values)
    print(f"OK — inserted and verified {len(values)} keys")

"""Buffered B-tree with amortized O(1) insertion.

Insertions go into an unsorted buffer. When the buffer fills, all keys
are flushed into the sorted B-tree in one batch, amortizing the O(log n)
splitting cost across buffer_size inserts.  Search and delete consult
both the buffer and the tree.

Worst-case insert per call: O(1)          (append to buffer)
Amortized insert per call:  O(1)          (flush cost shared)
Worst-case search:          O(log n + B)  (B = buffer_size)
Worst-case delete:          O(log n + B)
"""

from __future__ import annotations


class _Node:
    __slots__ = ("keys", "children", "leaf")

    def __init__(self, leaf: bool = False) -> None:
        self.keys: list = []
        self.children: list[_Node] = []
        self.leaf = leaf


class BTree:
    def __init__(self, t: int = 3, buffer_size: int = 64) -> None:
        if t < 2:
            raise ValueError("Minimum degree t must be >= 2")
        if buffer_size < 1:
            raise ValueError("buffer_size must be >= 1")
        self.t = t
        self.buffer_size = buffer_size
        self.root = _Node(leaf=True)
        self._buffer: list = []

    # ── Insert (amortized O(1)) ──────────────────────────────────────

    def insert(self, key) -> None:
        self._buffer.append(key)
        if len(self._buffer) >= self.buffer_size:
            self._flush_buffer()

    def _flush_buffer(self) -> None:
        for key in self._buffer:
            self._tree_insert(key)
        self._buffer.clear()

    def _tree_insert(self, key) -> None:
        root = self.root
        if len(root.keys) == 2 * self.t - 1:
            new_root = _Node()
            new_root.children.append(root)
            self._split_child(new_root, 0)
            self.root = new_root
        self._insert_non_full(self.root, key)

    def _insert_non_full(self, node: _Node, key) -> None:
        i = len(node.keys) - 1
        if node.leaf:
            node.keys.append(None)
            while i >= 0 and key < node.keys[i]:
                node.keys[i + 1] = node.keys[i]
                i -= 1
            node.keys[i + 1] = key
        else:
            while i >= 0 and key < node.keys[i]:
                i -= 1
            i += 1
            if len(node.children[i].keys) == 2 * self.t - 1:
                self._split_child(node, i)
                if key > node.keys[i]:
                    i += 1
            self._insert_non_full(node.children[i], key)

    def _split_child(self, parent: _Node, i: int) -> None:
        t = self.t
        full = parent.children[i]
        new_node = _Node(leaf=full.leaf)

        parent.children.insert(i + 1, new_node)
        parent.keys.insert(i, full.keys[t - 1])

        new_node.keys = full.keys[t:]
        full.keys = full.keys[: t - 1]

        if not full.leaf:
            new_node.children = full.children[t:]
            full.children = full.children[:t]

    # ── Search ───────────────────────────────────────────────────────

    def search(self, key) -> tuple[_Node | None, int]:
        """Return (node, index) where key lives in the tree, or (None, -1).

        Also checks the buffer first (O(B) linear scan).
        """
        for k in self._buffer:
            if k == key:
                return (None, -1)  # in buffer but not in tree node
        return self._search(self.root, key)

    def contains(self, key) -> bool:
        """Return True if key exists in buffer or tree."""
        for k in self._buffer:
            if k == key:
                return True
        node, idx = self._search(self.root, key)
        return node is not None

    def _search(self, node: _Node, key) -> tuple[_Node | None, int]:
        i = 0
        while i < len(node.keys) and key > node.keys[i]:
            i += 1
        if i < len(node.keys) and key == node.keys[i]:
            return (node, i)
        if node.leaf:
            return (None, -1)
        return self._search(node.children[i], key)

    # ── Delete ───────────────────────────────────────────────────────

    def delete(self, key) -> None:
        # Remove from buffer if present
        for i, k in enumerate(self._buffer):
            if k == key:
                self._buffer.pop(i)
                return
        self._delete(self.root, key)
        if not self.root.keys and not self.root.leaf:
            self.root = self.root.children[0]

    def _delete(self, node: _Node, key) -> None:
        t = self.t
        i = 0
        while i < len(node.keys) and key > node.keys[i]:
            i += 1

        if i < len(node.keys) and key == node.keys[i]:
            if node.leaf:
                node.keys.pop(i)
            else:
                self._delete_internal(node, i)
        elif node.leaf:
            return
        else:
            if len(node.children[i].keys) < t:
                self._fill(node, i)
            if i > len(node.keys):
                self._delete(node.children[i - 1], key)
            else:
                self._delete(node.children[i], key)

    def _delete_internal(self, node: _Node, i: int) -> None:
        t = self.t
        key = node.keys[i]

        if len(node.children[i].keys) >= t:
            pred = self._max_key(node.children[i])
            node.keys[i] = pred
            self._delete(node.children[i], pred)
        elif len(node.children[i + 1].keys) >= t:
            succ = self._min_key(node.children[i + 1])
            node.keys[i] = succ
            self._delete(node.children[i + 1], succ)
        else:
            self._merge(node, i)
            self._delete(node.children[i], key)

    def _min_key(self, node: _Node):
        while not node.leaf:
            node = node.children[0]
        return node.keys[0]

    def _max_key(self, node: _Node):
        while not node.leaf:
            node = node.children[-1]
        return node.keys[-1]

    def _fill(self, node: _Node, i: int) -> None:
        t = self.t
        if i > 0 and len(node.children[i - 1].keys) >= t:
            self._borrow_prev(node, i)
        elif i < len(node.children) - 1 and len(node.children[i + 1].keys) >= t:
            self._borrow_next(node, i)
        else:
            if i < len(node.children) - 1:
                self._merge(node, i)
            else:
                self._merge(node, i - 1)

    def _borrow_prev(self, node: _Node, i: int) -> None:
        child = node.children[i]
        sibling = node.children[i - 1]
        child.keys.insert(0, node.keys[i - 1])
        if not child.leaf:
            child.children.insert(0, sibling.children.pop())
        node.keys[i - 1] = sibling.keys.pop()

    def _borrow_next(self, node: _Node, i: int) -> None:
        child = node.children[i]
        sibling = node.children[i + 1]
        child.keys.append(node.keys[i])
        if not child.leaf:
            child.children.append(sibling.children.pop(0))
        node.keys[i] = sibling.keys.pop(0)

    def _merge(self, node: _Node, i: int) -> None:
        child = node.children[i]
        sibling = node.children[i + 1]
        child.keys.append(node.keys[i])
        child.keys.extend(sibling.keys)
        if not child.leaf:
            child.children.extend(sibling.children)
        node.keys.pop(i)
        node.children.pop(i + 1)

    # ── Range Query ──────────────────────────────────────────────────

    def range_query(self, lo, hi) -> list:
        """Return all keys k with lo <= k <= hi (tree + buffer)."""
        result: list = []
        self._range_query(self.root, lo, hi, result)
        for k in self._buffer:
            if lo <= k <= hi:
                result.append(k)
        result.sort()
        return result

    def _range_query(self, node: _Node, lo, hi, result: list) -> None:
        i = 0
        while i < len(node.keys):
            if not node.leaf and node.keys[i] >= lo:
                self._range_query(node.children[i], lo, hi, result)
            if lo <= node.keys[i] <= hi:
                result.append(node.keys[i])
            if node.keys[i] > hi:
                break
            i += 1
        if not node.leaf and (not node.keys or node.keys[-1] <= hi):
            self._range_query(node.children[i], lo, hi, result)

    # ── Utility ──────────────────────────────────────────────────────

    def flush(self) -> None:
        """Force-flush the buffer into the tree."""
        self._flush_buffer()

    def inorder(self) -> list:
        result: list = []
        self._inorder(self.root, result)
        result.extend(self._buffer)
        result.sort()
        return result

    def _inorder(self, node: _Node, result: list) -> None:
        for i, key in enumerate(node.keys):
            if not node.leaf:
                self._inorder(node.children[i], result)
            result.append(key)
        if not node.leaf:
            self._inorder(node.children[-1], result)

    def __repr__(self) -> str:
        return f"BTree(t={self.t}, buffer_size={self.buffer_size}, keys={self.inorder()})"


# ── Quick demo ──────────────────────────────────────────────────────

if __name__ == "__main__":
    import random

    tree = BTree(t=3, buffer_size=16)
    values = [10, 20, 5, 6, 12, 30, 7, 17, 3, 1, 25, 40, 50, 35]

    for v in values:
        tree.insert(v)

    print("Inorder:", tree.inorder())
    print(f"Buffer has {len(tree._buffer)} unflushed keys")

    print(f"Contains 12: {tree.contains(12)}")
    print(f"Contains 99: {tree.contains(99)}")

    print(f"Range [10, 30]: {tree.range_query(10, 30)}")

    tree.delete(6)
    tree.delete(17)
    print(f"After deleting 6, 17: {tree.inorder()}")

    # Stress test
    tree2 = BTree(t=8, buffer_size=128)
    data = random.sample(range(200_000), 50_000)
    for v in data:
        tree2.insert(v)
    tree2.flush()
    assert all(tree2.contains(v) for v in data)
    assert not tree2.contains(-1)
    assert tree2.inorder() == sorted(data)
    print(f"Stress test OK: {len(data)} keys inserted and verified")
